REQUIRED = {  # 위험등급별 제출 자료(가상 체크리스트)
    "저위험": {"서비스 설명서", "정확도 평가"},
    "중위험": {"서비스 설명서", "정확도 평가", "유해 응답 시험", "개인정보 점검"},
    "고위험": {"서비스 설명서", "정확도 평가", "유해 응답 시험", "개인정보 점검", "편향 평가", "사람 검수 절차"},
}
submitted = {
    "상담챗봇": ("중위험", {"서비스 설명서", "정확도 평가", "유해 응답 시험"}),
    "투자성향 추천": ("고위험", {"서비스 설명서", "정확도 평가", "유해 응답 시험", "개인정보 점검", "편향 평가"}),
}
for svc, (tier, got) in submitted.items():
    print(svc, tier, "빠진 자료:", sorted(REQUIRED[tier] - got))

# 상담챗봇 중위험 빠진 자료: ['개인정보 점검']
# 투자성향 추천 고위험 빠진 자료: ['사람 검수 절차']

CREATE TABLE approval(id TEXT, svc TEXT, decided DATE);
CREATE TABLE evidence(approval_id TEXT, kind TEXT);
INSERT INTO approval VALUES ('R-01','상담챗봇','2026-07-01'),('R-02','뉴스요약','2026-10-02'),('R-03','회의록요약','2026-11-05');
INSERT INTO evidence VALUES ('R-01','평가 보고서'),('R-01','심의 의사록'),('R-02','심의 의사록'),('R-03','평가 보고서'),('R-03','심의 의사록');

SELECT a.id, a.svc,
       COALESCE(SUM(e.kind = '평가 보고서'), 0) AS 평가,
       COALESCE(SUM(e.kind = '심의 의사록'), 0) AS 의사록
FROM approval a LEFT JOIN evidence e ON e.approval_id = a.id
GROUP BY a.id
HAVING 평가 = 0 OR 의사록 = 0;

-- R-02 | 뉴스요약 | 0 | 1
